-- Retry-safe creation (M1), generated by drizzle-kit. One row per document created with a client-generated id,
-- with no foreign key so it outlives the document. Existing rows are not touched: documents created before had
-- no client id, so they have no record.
CREATE TABLE "document_creations" (
	"document_id" uuid PRIMARY KEY NOT NULL,
	"request_hash" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
